"use client";
/* Mumu, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Mumu(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("mumu"); }, []);
  return React.createElement("piix-sprite", { "name": "mumu", ...piixAttrs(props) });
}

export default Mumu;
